from collections import deque

def max_sliding_window(a: list[int], k: int) -> list[int]:
    dq = deque()              # indices, values decreasing
    out = []
    for i, x in enumerate(a):
        if dq and dq[0] <= i - k:
            dq.popleft()      # expired
        while dq and a[dq[-1]] <= x:
            dq.pop()          # dominated
        dq.append(i)
        if i >= k - 1:
            out.append(a[dq[0]])
    return out

