int shortestSubarray(const vector<int>& a, long long K) {
    int n = (int)a.size();
    vector<long long> pre(n + 1, 0);
    for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + a[i];

    deque<int> dq;                 // indices into pre, values increasing
    int best = INT_MAX;
    for (int i = 0; i <= n; ++i) {
        while (!dq.empty() && pre[i] - pre[dq.front()] >= K) {
            best = min(best, i - dq.front());   // front can never do better later
            dq.pop_front();
        }
        while (!dq.empty() && pre[dq.back()] >= pre[i]) dq.pop_back();  // dominated
        dq.push_back(i);
    }
    return best == INT_MAX ? -1 : best;
}

