from collections import deque

def shortest_subarray(a: list[int], K: int) -> int:
    n = len(a)
    pre = [0] * (n + 1)
    for i, x in enumerate(a):
        pre[i + 1] = pre[i] + x

    dq = deque()                # indices into pre, values increasing
    best = float('inf')
    for i in range(n + 1):
        while dq and pre[i] - pre[dq[0]] >= K:
            best = min(best, i - dq.popleft())   # front cannot do better later
        while dq and pre[dq[-1]] >= pre[i]:
            dq.pop()            # dominated
        dq.append(i)
    return -1 if best == float('inf') else best

