struct DiffArray {
    vector<long long> d;
    explicit DiffArray(int n) : d(n + 1, 0) {}

    void rangeAdd(int l, int r, long long v) {   // inclusive [l, r]
        d[l] += v;
        d[r + 1] -= v;                           // cancel just past the end
    }
    vector<long long> materialize(int n) {       // call once, after all ops
        vector<long long> a(n);
        long long run = 0;
        for (int i = 0; i < n; ++i) { run += d[i]; a[i] = run; }
        return a;
    }
};

struct SparseTableMin {
    vector<vector<int>> t;
    vector<int> lg;

    explicit SparseTableMin(const vector<int>& a) {
        int n = (int)a.size();
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; ++i) lg[i] = lg[i / 2] + 1;
        int K = lg[n] + 1;
        t.assign(K, vector<int>(n));
        t[0] = a;
        for (int k = 1; k < K; ++k)
            for (int i = 0; i + (1 << k) <= n; ++i)
                t[k][i] = min(t[k - 1][i], t[k - 1][i + (1 << (k - 1))]);
    }
    int query(int l, int r) const {          // inclusive [l, r]
        int k = lg[r - l + 1];
        return min(t[k][l], t[k][r - (1 << k) + 1]);   // halves may overlap
    }
};

