class SparseTableMin:
    def __init__(self, a: list[int]):
        n = len(a)
        self.lg = [0] * (n + 1)
        for i in range(2, n + 1):
            self.lg[i] = self.lg[i // 2] + 1
        K = self.lg[n] + 1 if n else 1
        self.t = [list(a)]
        for k in range(1, K):
            prev, span = self.t[k - 1], 1 << (k - 1)
            self.t.append([min(prev[i], prev[i + span])
                           for i in range(n - (1 << k) + 1)])

    def query(self, l: int, r: int) -> int:      # inclusive [l, r]
        k = self.lg[r - l + 1]
        return min(self.t[k][l], self.t[k][r - (1 << k) + 1])   # halves may overlap

