struct NumMatrix {
    vector<vector<long long>> pre;   // (rows+1) x (cols+1), padded with zeros

    explicit NumMatrix(const vector<vector<int>>& m) {
        int rows = (int)m.size(), cols = rows ? (int)m[0].size() : 0;
        pre.assign(rows + 1, vector<long long>(cols + 1, 0));
        for (int i = 0; i < rows; ++i)
            for (int j = 0; j < cols; ++j)
                pre[i + 1][j + 1] = m[i][j]
                                  + pre[i][j + 1] + pre[i + 1][j]
                                  - pre[i][j];        // added twice, remove once
    }
    long long sumRegion(int r1, int c1, int r2, int c2) const {
        return pre[r2 + 1][c2 + 1] - pre[r1][c2 + 1]
             - pre[r2 + 1][c1] + pre[r1][c1];         // - - +
    }
};

