int sumSubarrayMins(const vector<int>& a) {
    const long long MOD = 1000000007LL;
    int n = (int)a.size();
    vector<long long> left(n), right(n);
    stack<int> st;

    // left[i]: how far the span can extend using PREVIOUS STRICTLY SMALLER
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        left[i] = st.empty() ? i + 1 : i - st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    // right[i]: NEXT SMALLER-OR-EQUAL -- the equality lives on exactly one side
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && a[st.top()] > a[i]) st.pop();
        right[i] = st.empty() ? n - i : st.top() - i;
        st.push(i);
    }
    long long total = 0;
    for (int i = 0; i < n; ++i)
        total = (total + a[i] % MOD * left[i] % MOD * right[i]) % MOD;
    return (int)total;
}
